                    let tracked au = maybe_au.tracked_take();
                    let tracked gva = proto.take_empty();
                    // gva.id() == gv_id, gva@ == None, gv@ == None
                    // update gv to Some(au)
                    gva.update(&mut gv, Some(au));
                    // gva@ == Some(au), gv@ == Some(au)
                    let tracked au_wrapped = Tracked(au);
                    assert(gv@ is Some);
                    assert(gv@->0 == au_wrapped@);
                    proto = Offering(au_wrapped);
                    // Store gva (now tracking Some(au)) outside the invariant
                    auth_au = Some(gva);
                }

                v = (value_perm, pend_perm, auth, gv, proto);
            }
