fn try_handshake(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
    requires
        self.wf(),
        au.pred().args(self),
    ensures
        match out {
            Some(ret_au) => ret_au == au,
            None => au.resolves(),
        }
{
    let tracked mut maybe_au = Some(au);
    let tracked mut auth_au: Option<GhostVarAuth<Option<FlipAU>>> = None;
    let res;

    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        res = self.pending.compare_exchange(Tracked(&mut pend_perm), 0, 1);

        proof {
            if res.is_ok() {
                // CAS 0->1 succeeded: proto was Empty, now put au into Offering
                let tracked au = maybe_au.tracked_take();
                let tracked mut gva = proto.take_empty();
                // gva.id() == gv_id, gva@ == None, gv@ == None
                // update gv to Some(au)
                gva.update(&mut gv, Some(au));
                // gva@ == Some(au), gv@ == Some(au)
                let tracked au_wrapped = Tracked(au);
                assert(gv@ is Some);
                assert(gv@->0 == au_wrapped@);
                proto = Offering(au_wrapped);
                // Store gva (now tracking Some(au)) outside the invariant
                auth_au = Some(gva);
            }

            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    if res.is_err() {
        return Some(Tracked(maybe_au.tracked_take()));
    }

    assert(auth_au is Some);

    let res;

    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 0);

        proof {
            if res.is_ok() {
                // CAS 1->0 succeeded: we can retract the offer
                let tracked mut gva = auth_au.tracked_take();
                let tracked au_tracked = proto.take_offer();
                // update gv back to None
                gva.update(&mut gv, None);
                assert(gv@ is None);
                assert(gva@ is None);
                assert(gva.id() == gv.id());
                proto = Empty(gva);
                // Return au via maybe_au
                maybe_au = Some(au_tracked.get());
            } else {
                // CAS 1->0 failed: pend_perm.value() != 1 before CAS
                // Use gva to learn gv@ == Some(au)
                let tracked gva = auth_au.tracked_borrow();
                gva.agree(&gv);
                // gva@ == Some(au), gv@ == Some(au)
                // Invariant cases: pend==0 requires gv@ is None (contradiction)
                // So pend != 0, and pend != 1 (CAS failed), so pend == 2
                // Accepted case: gv@->0.resolves()
                assert(gv@ is Some);
                assert(pend_perm.value() != 1); // CAS 1->0 failed
                // Rule out pend==0: would require gv@ is None, contradiction
                assert(pend_perm.value() != 0) by {
                    assert(gv@ == gva@);
                    assert(gv@ is Some);
                    if pend_perm.value() == 0 {
                        assert(gv@ is None); // from Empty invariant
                        assert(false);
                    }
                };
                assert(pend_perm.value() == 2);
                assert(proto is Accepted);
                assert(gv@->0.resolves());
                assert(gv@->0 == au);
                // au.resolves() is now established
            }
            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    if res.is_err() {
        // The other party took our offer (pending went 1->2 = Accepted)
        // They resolved our au already; au.resolves() is established above
        // We need to fix pending back to 0 and restore the protocol
        open_atomic_invariant!(self.inv.borrow() => v => {
            let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
            self.pending.store(Tracked(&mut pend_perm), 0);

            proof {
                let tracked mut gva = auth_au.tracked_take();
                gva.agree(&gv);
