                    // Accepted case: gv@->0.resolves()
                    assert(gv@ is Some);
                    assert(pend_perm.value() != 1); // CAS 1->0 failed
                    // Rule out pend==0: would require gv@ is None, contradiction
                    assert(pend_perm.value() != 0) by {
                        assert(gv@ == gva@);
                        assert(gv@ is Some);
                        if pend_perm.value() == 0 {
                            assert(gv@ is None); // from Empty invariant
                            assert(false);
                        }
                    };
                    assert(pend_perm.value() == 2);
                    assert(proto is Accepted);
                    assert(gv@->0.resolves());
                    assert(gv@->0 == au);
                    // au.resolves() is now established
                }
                v = (value_perm, pend_perm, auth, gv, proto);
            }
        });

        if res.is_err() {
            // The other party took our offer (pending went 1->2 = Accepted)
            // They resolved our au already; au.resolves() is established above
            // We need to fix pending back to 0 and restore the protocol
            open_atomic_invariant!(self.inv.borrow() => v => {
                let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
                self.pending.store(Tracked(&mut pend_perm), 0);

                proof {
                    let tracked mut gva = auth_au.tracked_take();
                    gva.agree(&gv);
                    // gva@ == Some(au), gv@ == Some(au), so gv@ is Some
                    assert(gv@ == gva@);
                    assert(gv@ is Some);
                    // From invariant: proto is Empty => pend==0 => gv@ is None (contrapositive)
                    // gv@ is Some => proto is not Empty => proto is Offering or Accepted
                    assert(!(proto is Empty)) by {
                        if proto is Empty {
                            assert(pend_perm.value() == 0);
                            assert(gv@ is None); // invariant Empty case
                            assert(false);
                        }
                    };
                    // Restore to Empty
                    gva.update(&mut gv, None);
                    assert(gv@ is None);
                    assert(gva@ is None);
                    proto = Empty(gva);
                    v = (value_perm, pend_perm, auth, gv, proto);
                }
            });

            return None;
        }

        Some(Tracked(maybe_au.tracked_take()))
    }
}

pub struct UserInv;
pub open spec const USER_INV: int = 5;
impl InvariantPredicate<Loc, FlagToken> for UserInv {
    open spec fn inv(id: Loc, token: FlagToken) -> bool {
        &&& token.id() == id
    }
}

